// ── Bank Statement Import (sao kê NH) types ──────────────────────────────────

import type { BankTemplateId } from './bankStatementTemplates';

/** Loại template được auto-detect từ file. */
export type BankStatementTemplateType = 'bao_no' | 'bao_co' | 'unc' | 'ctnb';

export interface BankStatementImportRow {
  rowIndex: number;
  transactionDate?: string;
  referenceCode?: string;
  amount?: number;
  debitAmount?: number;
  creditAmount?: number;
  /** Phí NH / lãi (tuyệt đối) khi template có cột phí. */
  feeAmount?: number;
  /** Thuế / VAT giao dịch (tuyệt đối) khi template có cột thuế. */
  taxAmount?: number;
  counterpartyName?: string;
  description?: string;
  bankAccountCode?: string;
  customerCode?: string;
  /** Ngân hàng đối tác (Remitter Bank) nếu có. */
  partnerBankName?: string;
  /**
   * Ghi chú user cạnh cột chính — 1 cột note:
   * diễn giải chi phí.
   */
  expenseNote?: string;
  /** Ghi chú user — mã KH (khi có ≥2 cột note). */
  noteCustomerCode?: string;
  /** Ghi chú user — tên KH (khi có ≥2 cột note). */
  noteCustomerName?: string;
  /** Template ngân hàng nhận diện được (mb/tcb/tpb/vp/gpb/generic). */
  bankTemplateId?: BankTemplateId;
  /** Gợi ý loại phiếu theo dòng: debit → bao_no, credit → bao_co. */
  suggestedVoucherType?: 'bao_no' | 'bao_co';
  /** Relative path + dòng nguồn (option 1): `{webkitRelativePath|fileName}:{lineno}` */
  importReference?: string;
  /** Batch reference codes tự động detected từ description (14-20 digits starting with 25). */
  detectedBatchRefs?: string[];
  /** User chọn/thêm manual batch ref. */
  manualBatchRef?: string;
  /** User đánh dấu là giao dịch batch. */
  isBatchTransaction?: boolean;
  /** Lý do confirm khi không có sao kê chi tiết. */
  batchConfirmReason?: string;
  /**
   * Mã loại định khoản được auto-detect từ nội dung CK (bankStatementPostingRules).
   * VD: MAT_BANG, LUONG, TT_NCC, PHI_NH, CHUA_PHAN_LOAI…
   */
  postingCategoryCode?: string;
  /** Nhãn hiển thị của loại định khoản. */
  postingCategoryLabel?: string;
}

export interface BankStatementImportRequest {
  monthCode: string; // YYYYMM
  bankStatementFile: string; // tên file sao kê
  batchPaymentFiles: string[]; // tên các file thanh toán lô
  rows: BankStatementImportRow[];
  /** Nếu true, BE skip dòng không có số tiền (thay vì báo error). */
  skipEmptyRows?: boolean;
}

export interface BankStatementDryRunRow {
  rowIndex: number;
  status: 'ok' | 'missing_customer' | 'error';
  errorMessage?: string;
  voucherType?: string;
  suggestedVoucherType?: string;
  importReference?: string;
  matchedCustomerId?: string;
  matchedCustomerCode?: string;
  matchedCustomerName?: string;
  amount?: number;
  description?: string;
  counterpartyName?: string;
  /** Batch reference codes detected from description. */
  detectedBatchRefs?: string[];
  /** Các batch ref match với file thanh toán lô. */
  matchedBatchRefs?: string[];
  /** Có file sao kê chi tiết cho batch này không. */
  hasBatchDetail?: boolean;
  /** Số dòng chi tiết trong file lô. */
  batchDetailLineCount?: number;
  /** User đánh dấu bỏ qua dòng này khi import (dù lỗi hay sẵn sàng). */
  skipOnImport?: boolean;
  /** Mã cửa hàng được gán cho giao dịch chi phí. */
  expenseStoreCode?: string;
  /** Tên cửa hàng. */
  expenseStoreName?: string;
  /** Đánh dấu là chi phí chung (không gán cửa hàng). */
  isCommonExpense?: boolean;
  /** Dòng chi tiết khi có file sao kê lô (master-detail). */
  batchDetailLines?: BatchDetailLine[];
}

export interface BatchDetailLine {
  /** STT trong file lô. */
  lineIndex: number;
  /** Tên người thụ hưởng. */
  beneficiaryName: string;
  /** Số tài khoản. */
  accountNumber?: string;
  /** Ngân hàng. */
  bankName?: string;
  /** Số tiền. */
  amount: number;
  /** Số FT / transaction reference (chỉ khi TC hoặc ô đúng dạng FT…). */
  ftNumber?: string;
  /**
   * Lý do lỗi khi TB — MB cột «Bút toán/Lý do» ghi message thay vì FT.
   * Không dùng làm ftNumber.
   */
  errorReason?: string;
  /** Mã chi nhánh. */
  branchCode?: string;
  /** Nội dung chuyển khoản (từ file thanh toán lô). */
  description?: string;
  /** Trạng thái giao dịch (Thành công / Thất bại…). */
  status?: string;
  /** Ngày giao dịch của lô (từ header sheet). */
  sheetDate?: string;
  /** Số tham chiếu lô (Ref No). */
  batchRef?: string;
  /**
   * Cột user thêm bên phải file CK LÔ — ghi chú nhân viên phân loại GD / companyId (vd. FM05).
   */
  staffNote?: string;
  /** companyId suy ra từ staffNote (nếu dạng mã ngắn). */
  companyCode?: string;
  /**
   * Chứng từ gốc lô: `{file}:tab:{tab}:{line}`
   * — file relative · tab = tên sheet · line = dòng 1-based trên sheet.
   */
  sourcePath?: string;
}

/** Tổng hợp tiền theo trạng thái dòng lô. */
export interface BatchAmountBreakdown {
  /** Tổng tất cả dòng. */
  totalAmount: number;
  /** Tổng Thành công — dùng khi khớp tiền với sao kê. */
  successAmount: number;
  /** Tổng Thất bại — không tham gia khớp tiền. */
  failedAmount: number;
  successCount: number;
  failedCount: number;
}

export interface BankStatementDryRunResult {
  dryRunId: string;
  rows: BankStatementDryRunRow[];
  totalRows: number;
  readyCount: number;
  missingCustomerCount: number;
  errorCount: number;
}

export interface BatchDetailInfo {
  /** bulkRef của lô. */
  bulkRef: string;
  /** Tên file batch. */
  batchFileName: string;
  /** Các dòng chi tiết trong lô. */
  lines: BatchDetailLine[];
  /** Tổng tiền batch (gross = TC + TB). */
  batchTotalAmount: number;
  /** Tổng Thành công — khớp sao kê. */
  batchSuccessAmount?: number;
  /** Tổng Thất bại. */
  batchFailedAmount?: number;
  /** Số dòng. */
  lineCount: number;
}

export interface NewCustomerInfo {
  name: string;
  customerGroupId: string;
  customerGroupCode?: string;
  parentGroupId?: string;
  /** Đối tượng cha (parent customer) — khi chọn sẽ auto-fill group 1. */
  parentCustomerId?: string;
  customerGroup2Id?: string;
  customerGroup3Id?: string;
  customerGroup4Id?: string;
  code?: string;
  autoGenerateCode: boolean;
}

export interface CustomerBankAccount {
  accountKind: string;
  bankName: string;
  accountNumber: string;
  branchName?: string;
  accountHolder?: string;
  isPrimary: boolean;
}

/** Chế độ sử dụng tài khoản ngân hàng khi chọn KH có sẵn. */
export type BankAccountUseMode = 'replace' | 'add_all';

export interface CustomerResolution {
  rowIndex: number;
  existingCustomerId?: string;
  newCustomer?: NewCustomerInfo;
  /** Chế độ xử lý tài khoản NH cho KH đã có. */
  bankAccountUseMode?: BankAccountUseMode;
  /** Danh sách các rowIndex khác cùng counterpartyName được auto-apply. */
  autoApplyRowIndices?: number[];
  /** Batch ref được chọn/xác nhận. */
  selectedBatchRef?: string;
  /** Lý do confirm khi batch không có sao kê chi tiết. */
  batchConfirmReason?: string;
  /** Đánh dấu bỏ qua dòng này khi import. */
  skipOnImport?: boolean;
  /** Gán chi phí cho cửa hàng. */
  expenseStoreCode?: string;
  expenseStoreName?: string;
  /** Đánh dấu là chi phí chung. */
  isCommonExpense?: boolean;
}

/** Gán chi phí cho cửa hàng / chi phí chung. */
export interface ExpenseAssignment {
  rowIndex: number;
  /** Mã cửa hàng (null = chi phí chung). */
  storeCode?: string | null;
  /** Tên cửa hàng. */
  storeName?: string;
  /** Nếu true, đây là chi phí chung. */
  isCommon: boolean;
}

export interface BankStatementImportExecute {
  dryRunId: string;
  customerResolutions: CustomerResolution[];
  /** Số dòng xử lý mỗi batch (default 50). */
  batchSize?: number;
  /** Các rowIndex được đánh dấu bỏ qua — sẽ không import. */
  skipRowIndices?: number[];
}

export interface BankStatementImportRowResult {
  rowIndex: number;
  status: 'imported' | 'skipped_duplicate' | 'error';
  voucherId?: string;
  voucherCode?: string;
  voucherType?: string;
  errorMessage?: string;
  importReference?: string;
  amount?: number;
  description?: string;
  /** Số bút toán / referenceCode để dedup. */
  referenceCode?: string;
  /** Mã cửa hàng được gán (từ resolution). */
  expenseStoreCode?: string;
  /** Tên cửa hàng. */
  expenseStoreName?: string;
  /** Đánh dấu là chi phí chung. */
  isCommonExpense?: boolean;
}

export interface BankStatementImportResult {
  totalRows: number;
  successCount: number;
  errorCount: number;
  duplicateSkippedCount: number;
  rowResults: BankStatementImportRowResult[];
}

